UPDATE knowledge_base 
SET 
  content = 'Designing Your Life proporciona un enfoque único para diseñar tu carrera y vida personal con el mismo rigor que un ingeniero diseña un producto. Las cuatro medidas de calidad: Salud (bienestar físico y mental), Riqueza (seguridad financiera), Amor (relaciones significativas), Juego (diversión y creatividad). Herramientas prácticas incluyen la Brújula Profesional, el Mapa de Caminos con 3 versiones de vida a 5 años (Plan A: trayectoria actual, Plan B: carrera alternativa, Plan C: sin restricciones económicas), y Conversaciones Generativas. Para emprendedores: diseña tu startup iterativamente. Para profesionales en transición: prototipa nuevas carreras. Para líderes: diseña equipo y cultura. Crea tus 3 planes, identifica valores, prototipa e itera continuamente.',
  estimated_read_time = 60,
  difficulty_level = 'intermedio',
  language = 'es'
WHERE title = 'Designing Your Life' OR title = 'Start with Why';

UPDATE knowledge_base 
SET 
  content = 'Grit es la combinación de pasión y perseverancia sostenida en el tiempo. No es solo trabajar duro, sino mantener dirección durante años. Los 4 pilares: Pasión (encuentra qué realmente importa), Práctica Deliberada (mejora estratégica), Propósito (entender el porqué y el impacto), Esperanza (creencia en mejora). Angela Duckworth descubrió que Grit predice éxito mejor que IQ o talento natural. Para desarrollar Grit: define tu pasión, practica deliberadamente cada día, conecta con tu propósito, cultiva mentalidad de crecimiento, rodéate de gente con Grit. Aplicable en carreras, emprendimiento y desarrollo personal.',
  estimated_read_time = 50,
  difficulty_level = 'intermedio',
  language = 'es'
WHERE title = 'Grit';

UPDATE knowledge_base 
SET 
  content = 'Mindset: La Nueva Psicología del Éxito de Carol Dweck propone dos mentalidades. Mentalidad Fija: creencia de que habilidades son inmutables, lleva a evitar desafíos y rendirse ante obstáculos. Mentalidad de Crecimiento: creencia de que puedes desarrollar habilidades mediante esfuerzo, te abre a desafíos y valoras retroalimentación. La ciencia del cerebro: plasticidad neuronal permite crear nuevas conexiones a cualquier edad, la práctica construye mielina mejorando velocidad. En educación, crecimiento mindset = mejores calificaciones. En negocios, genera innovación. No es binario - puedes tener growth mindset en algunas áreas. Transición: reconoce tu mentalidad, desafíate conscientemente, celebra esfuerzo, practica deliberadamente.',
  estimated_read_time = 55,
  difficulty_level = 'intermedio',
  language = 'es'
WHERE title = 'Mindset';

UPDATE knowledge_base 
SET 
  content = 'Atomic Habits de James Clear demuestra el poder del 1% de mejora: 1.01^365 = 37.78x mejor en un año. El sistema de 4 pasos: Señal (disparador), Anhelo (motivación), Respuesta (hábito), Recompensa (beneficio). El cambio no ocurre en grandes acciones sino en pequeños hábitos. Estrategias: incrementa fricción de malos hábitos, disminuye fricción de buenos, apila hábitos a rutinas existentes, diseña ambiente, cultiva identidad. Ejemplos: después de desayunar medita 5 min, después de reunión anota aprendizajes. La identidad es clave - no se trata de qué quieres lograr sino en quién quieres convertirte.',
  estimated_read_time = 65,
  difficulty_level = 'intermedio',
  language = 'es'
WHERE title = 'Atomic Habits';

UPDATE knowledge_base 
SET 
  content = 'The 48 Laws of Power de Robert Greene explora la dinámica del poder en la sociedad. Conceptos clave: Nunca ensombrezcas a tu jefe, guarda secretos, haz que otros actúen contra sus intereses, hazte indispensable, cultiva aura de misterio. Aunque el libro describe leyes amorales, el valor está en reconocer dinámicas de poder para protegeerte. En el mundo corporativo, muchas estas dinámicas operan. Estrategia ética: comprende el juego sin comprometer valores. Aplicación profesional: reconoce cuando estás siendo manipulado, construye alianzas estratégicas, cultiva influencia legítima. Para líderes: entiende poder pero úsalo éticamente para inspirar.',
  estimated_read_time = 70,
  difficulty_level = 'avanzado',
  language = 'es'
WHERE title = '48 Laws of Power' OR title = 'The 48 Laws of Power';

UPDATE knowledge_base 
SET 
  content = 'Nonviolent Communication de Marshall Rosenberg ofrece técnica para comunicación compasiva. Los 4 componentes: Observación (qué pasó sin evaluación), Sentimiento (cómo te hace sentir), Necesidad (qué es importante para ti), Pedido (qué específicamente pides). En lugar de acusar, expresas tu experiencia. Ejemplos: en conflictos laborales, en negociaciones, en relaciones. En el trabajo: mejora comunicación con jefes, colegas, clientes. El beneficio: reduces defensividad, construyes empatía, resuelves conflictos. Práctica: en próxima conversación difícil, estructura tu mensaje: observación clara, sentimiento honesto, necesidad auténtica, pedido específico. Transformador para liderazgo y relaciones profesionales.',
  estimated_read_time = 60,
  difficulty_level = 'intermedio',
  language = 'es'
WHERE title = 'Nonviolent Communication' OR title = 'Comunicación Efectiva para Líderes';
